122:   // Draw optical crosshair / alignment reticle over video feed
123:   updateReticleCanvas() {
124:     const canvas = document.getElementById('cle-cam-canvas');
125:     if (!canvas) return;
126: 
127:     const ctx = canvas.getContext('2d');
128:     const w = canvas.width = canvas.clientWidth || 320;
129:     const h = canvas.height = canvas.clientHeight || 200;
130:     ctx.clearRect(0, 0, w, h);
131: 
132:     if (this.reticleMode === 'none') return;
133: 
134:     ctx.strokeStyle = this.reticleColor;
135:     ctx.lineWidth = 1.5;
136:     const cx = w / 2;
137:     const cy = h / 2;
138: 
139:     if (this.reticleMode === 'crosshair' || this.reticleMode === 'bullseye') {
140:       // Horizontal and vertical hair
141:       ctx.beginPath();
142:       ctx.moveTo(0, cy); ctx.lineTo(w, cy);
143:       ctx.moveTo(cx, 0); ctx.lineTo(cx, h);
144:       ctx.stroke();
145: 
146:       // Tick marks along hair (5mm virtual visual scale)
147:       const tickStep = 15;
148:       for (let x = cx - 60; x <= cx + 60; x += tickStep) {
149:         ctx.beginPath(); ctx.moveTo(x, cy - 4); ctx.lineTo(x, cy + 4); ctx.stroke();
150:       }
151:       for (let y = cy - 60; y <= cy + 60; y += tickStep) {
152:         ctx.beginPath(); ctx.moveTo(cx - 4, y); ctx.lineTo(cx + 4, y); ctx.stroke();
153:       }
154:     }
155: 
156:     if (this.reticleMode === 'bullseye') {
157:       // Concentric alignment circles
158:       [15, 35, 60].forEach(r => {
159:         ctx.beginPath();
160:         ctx.arc(cx, cy, r, 0, Math.PI * 2);
161:         ctx.stroke();
162:       });
163:     }
164: 
165:     if (this.reticleMode === 'grid') {
166:       ctx.lineWidth = 0.8;
167:       ctx.strokeStyle = 'rgba(0, 255, 100, 0.4)';
168:       const step = 20;
169:       for (let x = 0; x < w; x += step) {
170:         ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
171:       }
172:       for (let y = 0; y < h; y += step) {
173:         ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
174:       }
175:       // Center accent
176:       ctx.strokeStyle = this.reticleColor;
177:       ctx.lineWidth = 1.5;
178:       ctx.beginPath(); ctx.moveTo(0, cy); ctx.lineTo(w, cy); ctx.moveTo(cx, 0); ctx.lineTo(cx, h); ctx.stroke();
179:     }
180:   }
